 export const TASA_IVA = 0.13;

+// RF-002: la tasa sale de TASA_IVA (número entre 0 y 1); si no está definida, vale 0.13. Un valor inválido es error.
+export function tasaIva(env = process.env) {
+  if (env.TASA_IVA === undefined) return TASA_IVA;
+  const texto = env.TASA_IVA;
+  const valor = Number(texto);
+  if (!/^\d+(\.\d+)?$/.test(texto) || valor < 0 || valor > 1) throw new RangeError(`TASA_IVA inválida: ${JSON.stringify(texto)}`);
+  return valor;
+}
